<?php
namespace App\Services;
use Illuminate\Http\Request;use Illuminate\Support\Facades\{DB,Validator};use Illuminate\Validation\ValidationException;
class CcsHumanRules{
public function fail(string $field,string $message):never{throw ValidationException::withMessages([$field=>$message]);}
public function owner($user):bool{return $user&&($user->ccs_active??false)&&app(CcsAdministration::class)->owner($user);}
public function phone(?string $raw):?string{if($raw===null||trim($raw)==='')return null;$raw=trim($raw);if(!preg_match('/^\+?[0-9 ()-]+$/D',$raw))$this->fail('phone','Enter a valid phone number.');$s=preg_replace('/\D/','',$raw);if(str_starts_with($s,'0094'))$s=substr($s,2);if(preg_match('/^0[1-9]\d{8}$/D',$s))$s='94'.substr($s,1);elseif(preg_match('/^[1-9]\d{8}$/D',$s))$s='94'.$s;if(str_starts_with($s,'94')){if(!preg_match('/^94[1-9]\d{8}$/D',$s))$this->fail('phone','Sri Lankan phone: +94 followed by exactly 9 digits, without the initial 0.');}elseif(!str_starts_with($raw,'+')||!preg_match('/^[1-9]\d{7,14}$/D',$s))$this->fail('phone','For an international phone, include + and the country code.');return '+'.$s;}
public function nic(?string $raw):?string{$s=mb_strtoupper(trim((string)$raw));if($s==='')return null;if(!preg_match('/^(?:\d{9}[VX]|\d{12})$/D',$s))$this->fail('nic','NIC must be 9 digits + V/X, or exactly 12 digits.');return $s;}
public function nicKey(?string $nic):?string{if(!$nic)return null;if(strlen($nic)===10)$nic='19'.substr($nic,0,5).'0'.substr($nic,5,4);return hash('sha256',$nic);}
public function plate(string $raw,string $kind='modern',?string $province=null):array{
$plate=mb_strtoupper(trim(preg_replace('/\s+/u',' ',$raw)));$province=mb_strtoupper(trim((string)$province));$allowed=['WP','CP','SP','NP','EP','NW','NC','SG','UP'];if($province!==''&&!in_array($province,$allowed,true))$this->fail('province','Choose a valid province.');
if(preg_match('/^(WP|CP|SP|NP|EP|NW|NC|SG|UP)[ -]+(.+)$/u',$plate,$m)){$province=$province?:$m[1];$plate=$m[2];}
if($kind==='temporary')return ['plate'=>'TEMP-'.\Illuminate\Support\Str::upper(\Illuminate\Support\Str::random(12)),'key'=>null,'kind'=>'temporary','province'=>$province];
if($kind==='modern'){if(!preg_match('/^([A-Z]{2,3})[ -]?(\d{4})$/D',$plate,$m)||$m[2]==='0000')$this->fail('registration_number','Use 2–3 English letters + 4 digits, e.g. ABC-0123. For older plates choose Old/Special.');$plate=$m[1].'-'.$m[2];}
elseif(!in_array($kind,['old','special'],true)||!preg_match('/^[A-Z0-9 ශ්‍රී-]{2,30}$/uD',$plate)||!preg_match('/\d/',$plate))$this->fail('registration_number','Check the old/special plate against the CR book; unsupported symbols are not allowed.');
$key=preg_replace('/[\s-]+/u','',$plate);return ['plate'=>$plate,'key'=>$key,'kind'=>$kind,'province'=>$province];}
public function approve(Request $r,string $kind,array $details,bool $request=true):?int{
if($this->owner($r->user()))return null;if(!app(CcsCashierRules::class)->check($r,$kind)){$actions=$r->attributes->get('rules_confirmed_actions',[]);$actions[$kind]=$details;$r->attributes->set('rules_confirmed_actions',$actions);return null;}$fingerprint=hash('sha256',json_encode([$kind,$details],JSON_UNESCAPED_UNICODE|JSON_PRESERVE_ZERO_FRACTION));$query=DB::table('ccs_rule_approvals')->where('requested_by',$r->user()->id)->where('fingerprint',$fingerprint)->where('status','approved')->whereNull('consumed_at')->where('expires_at','>',now());$approved=$query->first();if($approved)return (int)$approved->id;
$existing=DB::table('ccs_rule_approvals')->where('requested_by',$r->user()->id)->where('fingerprint',$fingerprint)->where('status','pending')->first();if(!$existing&&$request){$id=DB::table('ccs_rule_approvals')->insertGetId(['kind'=>$kind,'requested_by'=>$r->user()->id,'fingerprint'=>$fingerprint,'details'=>json_encode($details,JSON_UNESCAPED_UNICODE),'status'=>'pending','created_at'=>now(),'updated_at'=>now()]);app(CcsAdministration::class)->audit($r->user()->id,'rule_approval_requested','rule_approval',$id,['kind'=>$kind]);}else $id=$existing->id??0;
$this->fail('rules','Owner approval required for '.$kind.'. Request #'.$id.' is in Rules & Approvals. After approval, retry the same details.');}
public function consume(?int $id,int $userId):void{if(!$id)return;$n=DB::table('ccs_rule_approvals')->where('id',$id)->where('requested_by',$userId)->where('status','approved')->whereNull('consumed_at')->where('expires_at','>',now())->update(['consumed_at'=>now(),'status'=>'used','updated_at'=>now()]);if($n!==1)$this->fail('rules','Approval expired or was already used. Request approval again.');}
public function customer(Request $r,?int $id=null):void{
$old=$id?DB::table('customers')->find($id):null;if($old&&$old->is_system_walkin)$this->fail('name','The system walk-in account cannot be edited.');$name=trim(preg_replace('/\s+/u',' ',(string)$r->input('name')));if($name==='')$this->fail('name','Customer name is required.');$merge=['name'=>$name];
foreach(['phone','whatsapp'] as $field){if($id&&$r->input($field)==($old->$field??null))continue;try{$merge[$field]=$this->phone($r->input($field));}catch(ValidationException $e){$this->fail($field,collect($e->errors())->flatten()->first());}}if(!$id&&!($merge['phone']??null))$this->fail('phone','Customer phone is required.');
$raw=$r->input('nic');if(!$id||$raw!==($old->nic??null)){$nic=$this->nic($raw);$merge['nic']=$nic;$key=$this->nicKey($nic);if($nic){foreach(DB::table('customers')->whereNull('deleted_at')->when($id,fn($q)=>$q->where('id','!=',$id))->whereNotNull('nic')->get(['id','nic']) as $c){try{$other=$this->nic($c->nic);}catch(ValidationException){continue;}if($this->nicKey($other)===$key)$this->fail('nic','This NIC already belongs to customer #'.$c->id.'. Open that customer instead.');}}$r->attributes->set('rules_nic_key',$key);}
$email=$r->input('email');if($email!==null&&trim((string)$email)!=='')Validator::make(['email'=>trim($email)],['email'=>'email:rfc|max:254'])->validate();if($r->has('email'))$merge['email']=trim((string)$email)?:null;
$phone=$merge['phone']??$r->input('phone');if($phone&&(!$id||$phone!==($old->phone??null))){$matches=[];foreach(DB::table('customers')->whereNull('deleted_at')->when($id,fn($q)=>$q->where('id','!=',$id))->whereNotNull('phone')->get(['id','name','phone']) as $c){try{$p=$this->phone($c->phone);}catch(ValidationException){continue;}if($p===$phone)$matches[]=$c->id.': '.$c->name;}if($matches&&!$r->boolean('rules_duplicate_phone'))$this->fail('phone','Existing customer with this phone: '.implode(', ',array_slice($matches,0,4)).'. Review the record, then tick Shared phone confirmed if this is another person.');}
$r->merge($merge);
}
public function vehicle(Request $r,bool $again=false):void{
if(!$r->filled('registration_number')&&!$r->boolean('include_vehicle')&&!$r->has('customer_id'))return;$kind=$r->input('plate_kind','modern');$p=$this->plate((string)$r->input('registration_number'),$kind,$r->input('province'));
if($p['key'])foreach(DB::table('vehicles')->whereNull('deleted_at')->where('is_system_walkin',false)->get(['id','registration_number']) as $v){try{$old=$this->plate($v->registration_number,preg_match('/^(?:(?:WP|CP|SP|NP|EP|NW|NC|SG|UP)[ -]+)?[A-Z]{2,3}[ -]?\d{4}$/i',$v->registration_number)?'modern':'old');}catch(ValidationException){continue;}if($p['key']===$old['key'])$this->fail('registration_number','This plate is already registered as vehicle #'.$v->id.'. Use the existing vehicle.');}
$r->validate(['chassis_number'=>'nullable|string|max:80']);$chassis=mb_strtoupper(trim((string)$r->input('chassis_number')));if($chassis!==''&&!preg_match('/^[A-Z0-9-]+$/D',$chassis))$this->fail('chassis_number','Chassis/frame number may contain letters, numbers and hyphens; it need not have 17 characters.');if($chassis!==''&&!$r->boolean('rules_chassis_confirm'))foreach(DB::table('vehicles')->whereNull('deleted_at')->whereNotNull('chassis_number')->get(['chassis_number','id']) as $v){if(str_replace('-','',mb_strtoupper($v->chassis_number))===str_replace('-','',$chassis))$this->fail('chassis_number','Chassis/frame number is already on vehicle #'.$v->id.'. Check the vehicle, then confirm the duplicate warning.');}$r->attributes->set('rules_chassis',$chassis?:null);
$approval=null;if(in_array($kind,['old','special'],true)){$r->validate(['rules_reason'=>'required|string|min:5|max:500']);$approval=$this->approve($r,'old_special_plate',['plate'=>$p['plate'],'kind'=>$kind,'make'=>trim((string)$r->input('make')),'model'=>trim((string)$r->input('model')),'reason'=>trim($r->input('rules_reason'))],!$again);}
if($kind==='temporary'&&$r->attributes->has('rules_plate'))$p=$r->attributes->get('rules_plate');$r->merge(['registration_number'=>$p['plate']]);$r->attributes->set('rules_plate',$p);$r->attributes->set('rules_plate_approval',$approval);
}
public function vehicleExtras(Request $r):array{$p=$r->attributes->get('rules_plate');if(!$p)return [];return ['chassis_number'=>$r->attributes->get('rules_chassis'),'rules_key'=>$p['key'],'plate_kind'=>$p['kind'],'registration_province'=>$p['province']?:null];}
public function lock():void{DB::table('ccs_rules_mutex')->where('id',1)->increment('revision');}
}
